const $=s=>document.querySelector(s),view=$('#view'),today=new Date();today.setHours(0,0,0,0);let events=[],submissions=[],route='lab',month=new Date(today.getFullYear(),today.getMonth(),1),search='',googleClientId=localStorage.getItem('academic-desk-google-client-id')||'',googleTokenClient,deadlineTypeFilter='',deadlineQuickFilter='all',autoDriveSync=localStorage.getItem('academic-desk-auto-drive-sync')==='true',syncTimer;
const APP_VERSION='Academic Desk v26.11.09',NAV=[['lab','Lab Workspace Dashboard'],['events','All events'],['conferences','Conferences'],['journals','Journals & special issues'],['cfp','Call for papers'],['deadlines','Submission deadlines'],['calendar','Calendar'],['submissions','My submissions'],['notifications','Notifications'],['reports','Reports'],['backup','Data backup & sync'],['settings','Settings']];
const types=['Abstract submission','Full paper submission','Extended abstract','Registration','Camera-ready submission','Revised paper submission','Payment deadline','Conference date','Journal submission','Special issue deadline'];const stages=['Interested','Research in Progress','Abstract Prepared','Paper Drafting','Submitted','Under Review','Revision Required','Accepted','Camera-Ready Submitted','Completed','Rejected','Withdrawn'];
const id=()=>crypto.randomUUID(),dateIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,days=v=>{let [y,m,d]=String(v||'').split('-').map(Number),now=new Date();return Math.round((Date.UTC(y,m-1,d)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000)},esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const fmt=v=>v?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'numeric'}).format(new Date(v+'T00:00:00')):'Not set';
function demo(){let plus=n=>{let d=new Date(today);d.setDate(d.getDate()+n);return dateIso(d)};return[{id:id(),demo:true,title:'DEMO: International AI & Society Conference',type:'Conference',priority:'High',organizer:'Example Academic Network',publication:'Demo proceedings',country:'India',city:'New Delhi',mode:'Hybrid',scope:'International',startDate:plus(32),endDate:plus(34),tags:'Artificial Intelligence, Social Sciences',notes:'Demo record. Verify all information before acting.',deadlines:[{id:id(),type:'Abstract submission',date:plus(5),status:'Pending'},{id:id(),type:'Full paper submission',date:plus(15),status:'Pending'}],createdAt:Date.now(),updatedAt:Date.now()},{id:id(),demo:true,title:'DEMO: Inclusive Education Special Issue',type:'Journal Special Issue',priority:'Medium',organizer:'Example Journal',publication:'Journal of Example Studies',country:'Online',mode:'Online',scope:'International',startDate:'',tags:'Education, Accessibility',notes:'Demo record. No indexing claim is verified.',deadlines:[{id:id(),type:'Journal submission',date:plus(10),status:'Pending'}],createdAt:Date.now(),updatedAt:Date.now()},{id:id(),demo:true,title:'DEMO: Regional Research Methods Workshop',type:'Workshop',priority:'Low',organizer:'Example University',country:'India',city:'Varanasi',mode:'Offline',scope:'National',startDate:plus(21),endDate:plus(21),tags:'Research Methods',notes:'Demo record.',deadlines:[{id:id(),type:'Registration',date:plus(8),status:'Pending'}],createdAt:Date.now(),updatedAt:Date.now()}]}
async function init(){route=location.hash.slice(1)||'lab';events=await all('events');if(!events.length&&!localStorage.getItem('academic-desk-demo-dismissed')){events=demo();for(const e of events)await put('events',e)}submissions=await all('submissions');document.title=APP_VERSION;renderNav();bind();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js');updateConnection();scheduleCloudSync()}
function renderNav(){$('#nav').innerHTML=NAV.filter(([r])=>!['backup','settings'].includes(r)||labAdmin).map(([r,n])=>`<a href="#${r}" data-route="${r}" class="nav-link ${r===route?'active':''}">${n}</a>`).join('')}
function deadlines(){return events.flatMap(e=>(e.deadlines||[]).map(d=>({...d,event:e}))).sort((a,b)=>a.date.localeCompare(b.date))}function countType(t){return events.filter(e=>e.type===t).length}function urgency(d){let x=days(d);return x<=3?'red':x<=7?'orange':x<=15?'yellow':''}function active(e){return(e.deadlines||[]).some(d=>d.status!=='Completed')}
function render(){renderNav();$('#pageTitle').textContent=NAV.find(x=>x[0]===route)?.[1]||'Academic Desk';const map={dashboard:dashboard,events:eventList,conferences:()=>eventList(e=>e.type==='Conference'),journals:()=>eventList(e=>e.type==='Journal Special Issue'),cfp:()=>eventList(e=>e.type==='Call for Papers'),deadlines:deadlineList,calendar:calendar,submissions:submissionList,notifications:notifications,reports:reports,backup:backup,settings:settings};(map[route]||dashboard)()}
function dashboard(){let ds=deadlines(),up=ds.filter(d=>d.status!=='Completed'&&days(d.date)>=0),monthEvents=events.filter(e=>e.startDate&&new Date(e.startDate+'T00:00:00').getMonth()===today.getMonth());let cards=[[events.length,'Total upcoming events','events'],[countType('Conference'),'Conferences','events:Conference'],[up.filter(d=>d.type.includes('paper')||d.type.includes('Journal')).length,'Paper submissions','deadlines:paper'],[up.filter(d=>d.type==='Abstract submission').length,'Abstract deadlines','deadlines:Abstract submission'],[countType('Journal Special Issue'),'Special issues','events:Journal Special Issue'],[up.filter(d=>days(d.date)<=7).length,'Within 7 days','deadlines:week'],[ds.filter(d=>days(d.date)<0&&d.status!=='Completed').length,'Overdue','deadlines:overdue'],[events.filter(e=>!active(e)).length,'Completed events','events:completed']];view.innerHTML=`<div class="toolbar dashboard-tools"><button class="secondary" id="dashboardImportIcs">Import ICS</button><button class="secondary" id="dashboardRestore">Restore JSON backup</button><button class="primary" id="dashboardAdd">+ Add event</button></div><div class="cards">${cards.map(([v,l,f])=>`<button class="card stat dashboard-card" data-dashboard-filter="${f}" style="text-align:left"><span>${l}</span><strong>${v}</strong><small>${l==='Conferences'?monthEvents.length+' this month':'Click to view'}</small></button>`).join('')}</div><div class="grid"><section class="panel"><div class="section-head"><div><h2>Upcoming deadline timeline</h2><p class="muted">Click a deadline to open its event details.</p></div><button class="secondary" data-go="deadlines">Open tracker</button></div>${deadlineItems(up.slice(0,7))}</section><section class="panel"><div class="section-head"><div><h2>Event mix</h2><button class="secondary" data-go="events">Manage events</button></div>${Object.entries(events.reduce((a,e)=>(a[e.type]=(a[e.type]||0)+1,a),{})).map(([k,v])=>`<div class="pipeline-row"><span>${esc(k)}</span><b>${v}</b></div>`).join('')||'<p class="empty">No events yet.</p>'}<hr><h3 style="margin-top:15px">Submission progress</h3>${stages.slice(0,6).map(s=>{let v=submissions.filter(x=>x.stage===s).length;return `<div class="bar" title="${s}: ${v}"><i style="width:${Math.min(100,v*25)}%"></i></div>`}).join('')}</section></div>`;$('#dashboardImportIcs').onclick=importIcs;$('#dashboardRestore').onclick=()=>$('#importDialog').showModal();$('#dashboardAdd').onclick=()=>openEvent()}
function deadlineItems(ds){return ds.length?`<div class="list">${ds.map(d=>{let n=days(d.date),dt=new Date(d.date+'T00:00:00');return `<button class="item deadline-open" data-event-id="${d.event.id}" style="text-align:left;background:transparent;width:100%"><div class="date-box">${dt.getDate()}<small>${dt.toLocaleString(undefined,{month:'short'}).toUpperCase()}</small></div><div><b>${esc(d.event.title)}</b><div class="muted">${esc(d.type)} · ${esc(d.event.type)}</div></div><span class="deadline ${urgency(d.date)}">${n<0?Math.abs(n)+'d overdue':n===0?'Today':n+'d'}</span></button>`}).join('')}</div>`:'<p class="empty">No matching deadlines.</p>'}
function filteredEvents(fn=()=>true){let q=search.toLowerCase();return events.filter(e=>fn(e)&&(!q||[e.title,e.type,e.publication,e.organizer,e.country,e.tags].join(' ').toLowerCase().includes(q))).sort((a,b)=>(a.startDate||'9999').localeCompare(b.startDate||'9999'))}
function eventList(fn=()=>true){let list=filteredEvents(fn);view.innerHTML=`<div class="toolbar"><input id="pageSearch" value="${esc(search)}" placeholder="Search this list"><select id="modeFilter"><option value="">All modes</option><option>Online</option><option>Offline</option><option>Hybrid</option></select><select id="scopeFilter"><option value="">National and international</option><option>National</option><option>International</option></select><button class="primary" id="listAdd">+ Add event</button></div><section class="panel table-wrap"><table class="table"><thead><tr><th>Event</th><th>Type</th><th>Location</th><th>Next deadline</th><th>Actions</th></tr></thead><tbody>${list.map(e=>{let d=(e.deadlines||[]).filter(x=>x.status!=='Completed').sort((a,b)=>a.date.localeCompare(b.date))[0];return `<tr><td><button class="text-button event-open" data-id="${e.id}"><b>${esc(e.title)}</b></button>${e.demo?'<span class="badge">DEMO</span>':''}<div class="muted">${esc(e.organizer||e.publication||'No organizer')}</div></td><td>${esc(e.type)}</td><td>${esc(e.city||e.country||e.mode)}</td><td>${d?`<span class="deadline ${urgency(d.date)}">${fmt(d.date)}</span><div class="muted">${esc(d.type)}</div>`:'—'}</td><td><div class="actions"><button class="small edit" data-id="${e.id}">Edit</button><button class="small duplicate" data-id="${e.id}">Duplicate</button><button class="small danger delete" data-id="${e.id}">Delete</button></div></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No events match your search.</td></tr>'}</tbody></table></section>`;$('#pageSearch').oninput=e=>{search=e.target.value;render()};for(const s of ['modeFilter','scopeFilter'])$('#'+s).onchange=()=>{let m=$('#modeFilter').value,c=$('#scopeFilter').value;eventList(e=>(!m||e.mode===m)&&(!c||e.scope===c))};$('#listAdd').onclick=()=>openEvent()}
function deadlineList(){let ds=deadlines(),filter=deadlineQuickFilter;const draw=()=>{let x=ds.filter(d=>{if(deadlineTypeFilter&&deadlineTypeFilter==='paper'&&!(/paper|Journal/i.test(d.type)))return false;if(deadlineTypeFilter&&deadlineTypeFilter!=='paper'&&d.type!==deadlineTypeFilter)return false;if(filter==='all')return d.status!=='Completed';if(filter==='today')return days(d.date)===0;if(filter==='week')return days(d.date)>=0&&days(d.date)<=7;if(filter==='month')return days(d.date)>=0&&new Date(d.date+'T00:00:00').getMonth()===today.getMonth();if(filter==='overdue')return days(d.date)<0&&d.status!=='Completed';return d.status==='Completed'});$('#deadlineResults').innerHTML=deadlineItems(x)};view.innerHTML=`<div class="toolbar">${[['all','All pending'],['today','Today'],['week','This week'],['month','This month'],['overdue','Overdue'],['completed','Completed']].map(([v,n])=>`<button class="filter-btn" data-filter="${v}">${n}</button>`).join('')}${deadlineTypeFilter?`<button class="secondary" id="clearDeadlineType">Clear type: ${esc(deadlineTypeFilter)}</button>`:''}</div><section class="panel"><div class="section-head"><div><h2>Deadline tracker</h2><p class="muted">Red ≤3 days or overdue, orange ≤7, yellow ≤15, green later.</p></div></div><div id="deadlineResults"></div></section>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;deadlineQuickFilter=filter;draw()});let clear=$('#clearDeadlineType');if(clear)clear.onclick=()=>{deadlineTypeFilter='';draw()};draw()}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),last=new Date(y,m+1,0).getDate(),prev=new Date(y,m,0).getDate(),name=month.toLocaleString(undefined,{month:'long',year:'numeric'});let cells='';for(let i=0;i<42;i++){let day=i-first+1,other=false,mm=m;if(day<1){day=prev+day;mm=m-1;other=true}else if(day>last){day-=last;mm=m+1;other=true}let d=new Date(y,mm,day),iso=dateIso(d),items=[...events.filter(e=>e.startDate===iso).map(e=>({t:e.title,c:'',id:e.id})),...deadlines().filter(x=>x.date===iso).map(x=>({t:x.event.title+' · '+x.type,c:'due',id:x.event.id}))],shown=items.slice(0,2);cells+=`<div class="cal-day ${other?'muted':''} ${iso===dateIso(today)?'today':''}" data-date="${iso}"><b>${day}</b>${shown.map(x=>`<button class="cal-event ${x.c} calendar-open" data-event-id="${x.id}" title="${esc(x.t)}">${esc(x.t)}</button>`).join('')}${items.length>shown.length?`<span class="calendar-count">+${items.length-shown.length} more</span>`:''}</div>`}view.innerHTML=`<div class="toolbar"><button class="secondary" id="prevMonth">‹</button><b>${name}</b><button class="secondary" id="nextMonth">›</button><button class="secondary" id="importIcs">Import ICS</button><button class="secondary" id="exportIcs">Export ICS</button><button class="primary" id="calendarAdd">+ Add event</button></div><section class="panel"><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="cal-label">${x}</div>`).join('')}${cells}</div></section>`;$('#prevMonth').onclick=()=>{month.setMonth(m-1);render()};$('#nextMonth').onclick=()=>{month.setMonth(m+1);render()};$('#calendarAdd').onclick=()=>openEvent();$('#exportIcs').onclick=exportIcs;$('#importIcs').onclick=importIcs;document.querySelectorAll('.cal-day').forEach(x=>x.onclick=e=>{if(e.target.closest('.cal-event'))return;openEvent({startDate:x.dataset.date})})}
function submissionList(){view.innerHTML=`<div class="toolbar"><button class="primary" id="addSubmission">+ Add submission</button></div><section class="panel"><div class="section-head"><div><h2>Paper submission pipeline</h2><p class="muted">Track manuscript progress independently of an event.</p></div></div><div class="pipeline">${submissions.map(s=>`<div class="pipeline-row"><div><b>${esc(s.title)}</b><div class="muted">${esc(s.eventTitle||'Standalone submission')} · updated ${fmt(s.updated)}</div></div><select class="stage-select" data-id="${s.id}">${stages.map(x=>`<option ${x===s.stage?'selected':''}>${x}</option>`).join('')}</select><button class="small danger submission-delete" data-id="${s.id}">Delete</button></div>`).join('')||'<p class="empty">No submissions tracked yet.</p>'}</div></section>`;$('#addSubmission').onclick=async()=>{let title=prompt('Manuscript title');if(!title)return;let eventTitle=prompt('Related conference or journal (optional)')||'';let s={id:id(),title,eventTitle,stage:'Interested',updated:dateIso(today),updatedAt:Date.now()};submissions.push(s);await put('submissions',s);scheduleCloudSync();render()};document.querySelectorAll('.stage-select').forEach(x=>x.onchange=async()=>{let s=submissions.find(q=>q.id===x.dataset.id);s.stage=x.value;s.updated=dateIso(today);s.updatedAt=Date.now();await put('submissions',s);scheduleCloudSync();render()});document.querySelectorAll('.submission-delete').forEach(x=>x.onclick=async()=>{if(confirm('Delete this submission?')){await remove('submissions',x.dataset.id);submissions=submissions.filter(q=>q.id!==x.dataset.id);scheduleCloudSync();render()}})}
function notifications(){let ds=deadlines().filter(d=>d.status!=='Completed'&&days(d.date)>=0&&days(d.date)<=30);view.innerHTML=`<section class="panel"><div class="section-head"><div><h2>Reminder centre</h2><p class="muted">Browser reminders work when permission is granted and the app is open. Offline reminders use your local event data.</p></div><button class="primary" id="permission">Enable browser notifications</button></div>${deadlineItems(ds)}</section>`;$('#permission').onclick=async()=>{if(!('Notification'in window))return alert('Browser notifications are not available here.');let p=await Notification.requestPermission();alert('Notification permission: '+p)}}
function reports(){let ds=deadlines().filter(d=>d.status!=='Completed'&&days(d.date)>=0&&days(d.date)<=7);view.innerHTML=`<section class="panel"><div class="section-head"><div><h2>Weekly academic deadline report</h2><p class="muted">Generated from your local database.</p></div><button class="primary" id="printReport">Print report</button></div>${deadlineItems(ds)}</section>`;$('#printReport').onclick=()=>window.print()}
function backupOnline(){view.innerHTML=`<div class="grid"><section class="panel"><h2>Portable academic database</h2><p class="muted" style="margin:8px 0 16px">Create a JSON backup containing events and submission workflow records. Restore only backups you trust.</p><div class="actions"><button id="exportJson" class="primary">Export JSON backup</button><button id="openImport" class="secondary">Restore JSON backup</button><button id="clearDemo" class="secondary">Remove demo records</button></div></section><section class="panel"><h2>Google Drive sync</h2><p id="syncInfo" class="muted" style="margin:8px 0 16px">${googleClientId?'Configured. Your backup stays in Drive’s private app-data folder.':'Add a Google OAuth client ID in Settings to enable sync.'}</p><div class="actions"><button id="syncNow" class="primary">Upload to Google Drive</button><button id="restoreDrive" class="secondary">Restore from Drive</button></div><p class="muted" style="margin-top:12px">Works only while online. Your local database remains usable offline.</p></section></div>`;$('#exportJson').onclick=exportJson;$('#openImport').onclick=()=>$('#importDialog').showModal();$('#clearDemo').onclick=async()=>{if(confirm('Remove only demo records?')){for(const e of events.filter(e=>e.demo)){await remove('events',e.id)}events=events.filter(e=>!e.demo);render()}};$('#syncNow').onclick=()=>googleSync('upload');$('#restoreDrive').onclick=()=>googleSync('restore')}
function settingsOnline(){view.innerHTML=`<section class="panel"><h2>Workspace settings</h2><p class="muted" style="margin:8px 0 16px">This PWA stores data in IndexedDB on this browser. Install it from your browser’s app menu for desktop-style use and offline access after its first load.</p><div class="actions"><button class="secondary" id="dark">Toggle theme</button><button class="secondary" id="resetSearch">Clear search</button></div></section><section class="panel" style="margin-top:18px"><h2>Google Drive connection</h2><p class="muted" style="margin:8px 0 14px">Use the same OAuth client ID and Google account on every device. Automatic sync combines records by their latest update time whenever you save while online. A sign-in may still be required on each device.</p><label>Google OAuth client ID<input id="googleClientId" value="${esc(googleClientId)}" placeholder="1234567890-abc.apps.googleusercontent.com"></label><label style="display:flex;grid-template-columns:auto 1fr;align-items:center;gap:8px;margin-top:14px"><input id="autoDriveSync" type="checkbox" ${autoDriveSync?'checked':''} style="width:auto">Automatically sync changes when online</label><div class="actions" style="margin-top:12px"><button id="saveGoogleClient" class="primary">Save Google configuration</button><button id="connectDrive" class="secondary">Connect and sync now</button><button id="clearGoogleClient" class="secondary">Disconnect</button></div></section>`;$('#dark').onclick=toggleTheme;$('#resetSearch').onclick=()=>{search='';render()};$('#saveGoogleClient').onclick=()=>{let v=$('#googleClientId').value.trim();if(!v.endsWith('.apps.googleusercontent.com'))return alert('Enter a valid Google OAuth web client ID.');googleClientId=v;autoDriveSync=$('#autoDriveSync').checked;localStorage.setItem('academic-desk-google-client-id',v);localStorage.setItem('academic-desk-auto-drive-sync',String(autoDriveSync));alert('Google Drive configuration saved.');render()};$('#connectDrive').onclick=()=>googleSync('sync');$('#clearGoogleClient').onclick=()=>{googleClientId='';autoDriveSync=false;localStorage.removeItem('academic-desk-google-client-id');localStorage.removeItem('academic-desk-auto-drive-sync');render()}}
function deadlineRow(d={type:'Abstract submission',date:'',status:'Pending'}){return `<div class="deadline-row"><select name="deadlineType">${types.map(x=>`<option ${x===d.type?'selected':''}>${x}</option>`).join('')}</select><input name="deadlineDate" type="date" value="${d.date||''}"><select name="deadlineStatus"><option ${d.status==='Pending'?'selected':''}>Pending</option><option ${d.status==='Completed'?'selected':''}>Completed</option><option ${d.status==='Archived'?'selected':''}>Archived</option></select><button type="button" class="small danger remove-deadline">Remove</button></div>`}
function openEvent(data={}){let form=$('#eventForm');form.reset();$('#deadlineFields').innerHTML=(data.deadlines||[{type:'Abstract submission',date:data.startDate||'',status:'Pending'}]).map(deadlineRow).join('');for(const[k,v]of Object.entries(data)){let f=form.elements[k];if(f&&k!=='deadlines')f.value=v||''}$('#eventDialogTitle').textContent=data.id?'Edit academic event':'Add academic event';$('#eventDialog').showModal()}
async function saveEvent(){let f=$('#eventForm');if(!f.reportValidity())return;let value=Object.fromEntries(new FormData(f));let old=events.find(e=>e.id===value.id);let rows=[...document.querySelectorAll('.deadline-row')];value.deadlines=rows.map((r,i)=>({id:old?.deadlines?.[i]?.id||id(),type:r.querySelector('[name=deadlineType]').value,date:r.querySelector('[name=deadlineDate]').value,status:r.querySelector('[name=deadlineStatus]').value})).filter(d=>d.date);if(!value.deadlines.length&&value.startDate)value.deadlines=[{id:id(),type:'Conference date',date:value.startDate,status:'Pending'}];value.id=value.id||id();value.demo=false;value.createdAt=old?.createdAt||Date.now();value.updatedAt=Date.now();events=old?events.map(e=>e.id===value.id?value:e):[...events,value];await put('events',value);scheduleCloudSync();$('#eventDialog').close();render()}
function detail(event){let d=(event.deadlines||[]).sort((a,b)=>a.date.localeCompare(b.date));$('#detailContent').innerHTML=`<div class="modal-head"><div><h2>${esc(event.title)}</h2><p class="muted">${esc(event.type)}${event.demo?' · DEMO RECORD':''}</p></div><button type="button" class="icon" data-close="detailDialog">×</button></div><div class="detail-grid">${[['Organizer',event.organizer],['Journal / conference',event.publication],['Location',[event.city,event.country,event.mode].filter(Boolean).join(', ')],['Scope',event.scope],['Dates',event.startDate?fmt(event.startDate)+(event.endDate?' – '+fmt(event.endDate):''):'Not set'],['Indexing',event.indexing],['Tags',event.tags],['Fee',event.fee]].map(([k,v])=>`<div><b>${k}</b>${esc(v||'Not set')}</div>`).join('')}</div><h3>Important dates</h3>${deadlineItems(d.map(x=>({...x,event})).filter(Boolean))}<p style="margin-top:14px">${esc(event.notes||'No notes')}</p><div class="modal-footer"><button class="secondary detail-edit" data-id="${event.id}">Edit event</button><button class="secondary mark-complete" data-id="${event.id}">Mark completed</button>${event.website?`<a class="primary" href="${esc(event.website)}" target="_blank" rel="noopener">Official website</a>`:''}</div>`;$('#detailDialog').showModal()}
function snapshot(){return{version:1,exportedAt:new Date().toISOString(),events,submissions}}
function loadGoogleScript(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.oauth2)return resolve();let script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(Error('Could not load Google sign-in. Check your connection.'));document.head.append(script)})}
async function googleToken(silent=false){if(!googleClientId)throw Error('Add your Google OAuth client ID in Settings first.');await loadGoogleScript();return new Promise((resolve,reject)=>{googleTokenClient=google.accounts.oauth2.initTokenClient({client_id:googleClientId,scope:'https://www.googleapis.com/auth/drive.appdata',callback:r=>r.error?reject(Error(r.error)):resolve(r.access_token)});googleTokenClient.requestAccessToken({prompt:silent?'':'consent'})})}
